description:
{
  "image_category": "TECHNICAL_DIAGRAM",
  "summary": "Hình ảnh là bản vẽ kỹ thuật đen trắng minh họa hình dạng và bố trí lắp đặt của biển số W.239a và W.239b theo quy định tại Điều C.39 QCVN 41:2024/BGTVT.",
  "items": [
    {
      "identifier": "Biển số W.239a",
      "visual_or_geometric_features": "Hình chữ nhật đứng, viền nét mảnh, bên trong có dòng chữ 'ĐƯỜNG CÁP ĐIỆN Ở PHÍA TRÊN' (giả định theo chuẩn biển báo), được đặt phía trên.",
      "meaning_or_specification": "Được đặt ở những nơi có đường dây điện cắt ngang phía trên tuyến đường, dùng để cảnh báo tài xế về sự hiện diện của cáp điện ở phía trên."
    },
    {
      "identifier": "Biển số S.509a",
      "visual_or_geometric_features": "Hình chữ nhật đứng, viền nét mảnh, bên trong có dòng chữ 'CHIỀU CAO AN TOÀN' (giả định theo chuẩn biển báo), được đặt ngay phía dưới biển W.239a.",
      "meaning_or_specification": "Kèm theo biển W.239a để chỉ rõ chiều cao an toàn cho phép của phương tiện khi đi qua khu vực có cáp điện."
    },
    {
      "identifier": "Biển số W.239b",
      "visual_or_geometric_features": "Hình chữ nhật đứng, viền nét mảnh, bên trong có dòng chữ 'CHIỀU CAO TĨNH KHÔNG THỰC TẾ' (giả định theo chuẩn biển báo), được đặt riêng biệt.",
      "meaning_or_specification": "Được đặt tại các vị trí có khoảng cách từ điểm cao nhất của mặt đường đến điểm thấp nhất của chướng ngại vật bị giới hạn, nhằm báo chiều cao tĩnh không thực tế."
    },
    {
      "identifier": "Bố trí lắp đặt",
      "visual_or_geometric_features": "Hai biển W.239a và S.509a được vẽ chồng lên nhau theo chiều dọc, biển W.239b được vẽ riêng biệt bên cạnh hoặc dưới cùng (tùy ngữ cảnh lắp đặt thực tế).",
      "meaning_or_specification": "Biển được đặt phía bên phải cho cả hai chiều đường xe chạy. Khi chiều cao an toàn > 5,5 m không phải đặt biển W.239(a, b), ngoại trừ các trường hợp các đoạn đường có yêu cầu khai thác đặc biệt."
    }
  ]
}
